// Manrope Medium (peso 500), file TTF codificato in base64.
//
// Perche' una stringa e non il file .ttf letto a runtime con Deno.readFile:
// "supabase functions deploy" (il percorso senza Docker, quello usato in
// questo progetto) non include nel bundle i file statici che non sono
// importati come modulo. Un Deno.readFile(new URL('./manrope-medium.ttf', ...))
// funziona in locale ma da 404 in produzione, perche' il file .ttf non viene
// caricato insieme a index.ts/pdf.ts. Il meccanismo documentato per i file
// statici (static_files in supabase/config.toml) richiede invece un deploy
// via Docker per essere applicato, non disponibile in questo ambiente.
// Una costante TS con i byte in base64 entra nel bundle come un modulo
// qualunque, senza toccare config.toml ne' dipendere da Docker.
//
// Rigenerare da Google Fonts risolvendo
// https://fonts.googleapis.com/css2?family=Manrope:wght@500
// con uno user agent che richiede TTF (es. Android 2.2), poi:
//   python3 -c "import base64; print(base64.b64encode(open('manrope-medium.ttf','rb').read()).decode())"
export const MANROPE_MEDIUM_BASE64 =
  '';
